{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"City of Los Angeles Just Cause for Eviction Ordinance (JCO)","requirement":"A landlord may not terminate a tenancy without just cause and must provide relocation assistance for no-fault evictions. A tenancy is covered only if the tenant has lived in the unit at least six months or the original lease has expired, whichever comes first.","key_value":null,"coverage_conditions":"Most residential rental properties in the City of Los Angeles that are not regulated by the Rent Stabilization Ordinance, where the tenant has lived in the unit at least six months or the original lease expired, whichever comes first.","applicability":{"conditions":[],"per_tenancy":"Tenant must have lived in the unit at least six months or the original lease must have expired, whichever comes first.","coverage_quotes":[]},"exemptions":"Transient hotels, licensed care facilities, fraternity or sorority houses, an owner's roommate, cooperatives under certain circumstances, some non-profit facilities for the homeless or short-term treatment centers for substance abuse, and some properties owned by HACLA or the government.","penalty":null,"effective_date":null,"valid_through":null,"citation":"Los Angeles Just Cause Ordinance (L.A.M.C. §165.00 et seq.)","quoted_span":"It prohibits terminations of tenancies without just cause and requires relocation assistance for no-fault evictions.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles bar on eviction for non-payment of rent below Fair Market Rent","requirement":"A landlord may not evict a tenant who has fallen behind in rent unless the amount owed is higher than the Fair Market Rent for the unit's bedroom size.","key_value":"amount owed must exceed the Fair Market Rent (FMR)","coverage_conditions":"All RSO and JCO rental units in the City of Los Angeles.","applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":"2023-03-27","valid_through":null,"citation":"Evictions for Non-Payment of Rent (City of Los Angeles)","quoted_span":"Effective March 27, 2023, landlords may not evict a tenant who falls behind in rent unless the tenant owes an amount higher than the Fair Market Rent (FMR).","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"CA","category":"rent_increase_limits","lifecycle":"enacted","title":"California Tenant Protection Act of 2019 (AB 1482) rent increase cap","requirement":"Annual rent increases for covered units are limited to 5% plus the regional cost-of-living change, or 10%, whichever is lower; for August 1, 2024 to July 31, 2025 the maximum was 8.9%.","key_value":"5% + CPI, max 10%; 8.9% for Aug 1, 2024–Jul 31, 2025","coverage_conditions":"Units older than 15 years (rolling basis), excluding units constructed within 15 years, income-restricted units, certain dormitories, qualifying two-unit owner-occupied properties, qualifying single-family homes and condominiums, and RSO units.","applicability":{"conditions":[{"type":"built_within_years","role":"exempt","years":15,"basis":"construction"},{"type":"other","role":"exempt","text":"units restricted by a deed or recorded document limiting affordability to low- or moderate-income households"},{"type":"owner","role":"exempt","who":"two-unit property with the second unit occupied by the owner for the whole tenancy","unit_limit":2},{"type":"other","role":"exempt","text":"single-family homes and condominiums not owned by a trust, corporation, or LLC with a corporate member, with written notice to the tenant"}],"per_tenancy":null,"coverage_quotes":["may regulate the rent amount in buildings that are older than 15 years old","Units that were constructed within the last 15 years","A two-unit property, provided the second unit was occupied by an owner of the property for the entire period of the tenancy."]},"exemptions":"Units built within the last 15 years; units restricted by a deed or recorded document to low- or moderate-income households; certain dormitories; a two-unit property with the second unit owner-occupied for the whole tenancy; qualifying single-family homes and condominiums; units already subject to the City's RSO.","penalty":null,"effective_date":null,"valid_through":null,"citation":"AB 1482 (Cal. Civ. Code § 1947.12)","quoted_span":"Effective August 1, 2024 to July 31, 2025, the maximum allowable increase is 8.9%.","interaction":"Yields to local rent control: units already subject to the City's Rent Stabilization Ordinance are exempt from AB 1482.","relations":[{"type":"yields_to_local","quote":"Units that are already subject to the City’s RSO."}],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D040-01","n_rules":3,"note":null}

